pub fn generate_content_script_js(fn_name: &str, crate_name: &str) -> String {
    let wasm_name = crate_name.replace('-', "_");
    let wrapper_name = format!("__oxichrome_cs_{fn_name}");

    format!(
        r#"// Auto-generated by oxichrome. Do not edit.
// Content script: {fn_name}
(async () => {{
    try {{
        const src = chrome.runtime.getURL('wasm/{wasm_name}.js');
        const wasm = await import(src);
        await wasm.default();
        wasm.{wrapper_name}();
        console.log('[oxichrome] Content script "{fn_name}" initialized.');
    }} catch (e) {{
        console.error('[oxichrome] Content script "{fn_name}" failed to initialize:', e);
    }}
}})();
"#
    )
}

/// Where a page's loader script goes: beside its HTML, same stem.
pub fn page_js_path(page: &Page) -> String {
    format!("{}.js", page.path.trim_end_matches(".html"))
}

fn escape_html(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}

/// The page shell: a language (screen readers and automatic translation need
/// one), a viewport, its stylesheets in order, and the loader. Absolute paths,
/// so a page at any depth finds the shared assets.
pub fn generate_page_html(page: &Page) -> String {
    let title = escape_html(page.title.as_deref().unwrap_or(&page.fn_name));
    let css: String = page
        .css
        .iter()
        .map(|href| format!("<link rel=\"stylesheet\" href=\"/{}\">\n", escape_html(href.trim_start_matches('/'))))
        .collect();
    let script = page_js_path(page);
    let script = script.rsplit('/').next().unwrap_or(&script);
    format!(
        r#"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
{css}</head>
<body>
<script type="module" src="{script}"></script>
</body>
</html>
"#
    )
}

pub fn generate_page_js(page: &Page, crate_name: &str) -> String {
    let wasm_name = crate_name.replace('-', "_");
    let mount = format!("__oxichrome_mount_page_{}", page.fn_name.to_lowercase());
    format!(
        r#"// Auto-generated by oxichrome. Do not edit.
import init, {{ {mount} }} from '/wasm/{wasm_name}.js';

try {{
    await init();
    {mount}();
}} catch (e) {{
    console.error('[oxichrome] Page init failed:', e);
    document.body.textContent = 'Error: ' + e.message;
}}
"#
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::source_parser::EventHandler;

    #[test]
    fn test_background_js_es_module() {
        let metadata = ExtensionMetadata {
            name: Some("Test".to_string()),
            version: Some("1.0.0".to_string()),
            description: None,
            permissions: vec![],
            host_permissions: vec![],
            background_functions: vec!["start".to_string()],
            event_handlers: vec![EventHandler {
                fn_name: "handle_install".to_string(),
                namespace: "runtime".to_string(),
                event_name: "on_installed".to_string(),
            }],
            has_popup: false,
            has_options_page: false,
            content_scripts: vec![],
            pages: vec![],
        };

        let js = generate_background_js(&metadata, "counter-extension");
        assert!(js.contains(
            "import init, { __oxichrome_bg_start, __oxichrome_register_handle_install }"
        ));
        assert!(js.contains("from './wasm/counter_extension.js'"));
        assert!(js.contains("await init();"));
        assert!(js.contains("__oxichrome_register_handle_install();"));
        assert!(js.contains("__oxichrome_bg_start();"));
    }

    #[test]
    fn test_popup_html() {
        let html = generate_popup_html();
        assert!(html.contains("src=\"popup.js\""));
        assert!(html.contains("min-width: 240px"));
        assert!(!html.contains("import init"));
    }

    #[test]
    fn test_popup_js() {
        let js = generate_popup_js("counter-extension");
        assert!(js.contains("__oxichrome_mount_popup"));
        assert!(js.contains("counter_extension.js"));
        assert!(js.contains("await init();"));
    }

    #[test]
    fn test_options_html() {
        let html = generate_options_html();
        assert!(html.contains("src=\"options.js\""));
        assert!(!html.contains("import init"));
    }

    #[test]
    fn test_options_js() {
        let js = generate_options_js("my-ext");
        assert!(js.contains("__oxichrome_mount_options"));
        assert!(js.contains("my_ext.js"));
        assert!(js.contains("await init();"));
    }

    #[test]
    fn test_content_script_js() {
        let js = generate_content_script_js("inject", "my-extension");
        assert!(js.contains("chrome.runtime.getURL('wasm/my_extension.js')"));
        assert!(js.contains("__oxichrome_cs_inject"));
        assert!(js.contains("await wasm.default()"));
        assert!(js.contains("Content script \"inject\" initialized."));
        // Must NOT start with a static import statement
        assert!(!js.starts_with("import"));
    }

    fn page() -> Page {
        Page {
            fn_name: "NewTab".into(),
            path: "src/pages/newtab/index.html".into(),
            title: Some("New <Tab>".into()),
            css: vec!["assets/theme.css".into(), "/assets/newtab.css".into()],
        }
    }

    #[test]
    fn test_page_html_has_language_viewport_css_and_loader() {
        let html = generate_page_html(&page());
        assert!(html.contains(r#"<html lang="en">"#));
        assert!(html.contains(r#"<meta name="viewport""#));
        assert!(html.contains("<title>New &lt;Tab&gt;</title>"));
        let theme = html.find(r#"href="/assets/theme.css""#).unwrap();
        let newtab = html.find(r#"href="/assets/newtab.css""#).unwrap();
        assert!(theme < newtab, "stylesheets keep their order");
        assert!(html.contains(r#"<script type="module" src="index.js"></script>"#));
    }

    #[test]
    fn test_page_js_mounts_its_component_from_the_root_wasm() {
        let js = generate_page_js(&page(), "reader-ext");
        assert!(js.contains("import init, { __oxichrome_mount_page_newtab } from '/wasm/reader_ext.js';"));
        assert!(js.contains("__oxichrome_mount_page_newtab();"));
        assert_eq!(page_js_path(&page()), "src/pages/newtab/index.js");
    }

    #[test]
    fn test_page_title_defaults_to_the_component_name() {
        let html = generate_page_html(&Page { title: None, ..page() });
        assert!(html.contains("<title>NewTab</title>"));
    }
}
